"use strict";

/**
 * rx-session-token — the ONE implementation of this app's auth primitive.
 *
 * Shipped as a Lambda layer (AuthLayer in template.yaml) and required as the
 * bare specifier `rx-session-token`. It exists as a layer rather than a shared
 * file because SAM packages each function's CodeUri directory on its own: a
 * require reaching into a sibling function's folder resolves locally, builds
 * green, and throws "Cannot find module" on the first real invocation.
 *
 * The `nodejs/node_modules/<name>` layout is deliberate. Lambda puts
 * /opt/nodejs/node_modules on NODE_PATH, so a bare require resolves there at
 * runtime; the repo root declares the same package as a file: dependency, so the
 * identical bare require resolves for tests. Requiring "/opt/nodejs/..." by
 * absolute path would work in Lambda but is unresolvable anywhere else, and a
 * bundler alias cannot intercept require() from a CommonJS module.
 *
 * Before this layer the same HMAC logic was copy-pasted into four places
 * (processPrescription/shared.js, notifyUser/email.js, cancelReminders/lib.js,
 * getSchedules/index.js). Four copies of an auth primitive means a fix applied
 * to one of them leaves the other three wrong, with nothing to say so.
 *
 * TOKEN FORMAT
 *   base64url(JSON {uid, exp}) "." base64url(HMAC-SHA256(secret, payload))
 * where exp is Unix seconds. The payload is signed, not encrypted — it is
 * readable by anyone holding the token, so it must never carry anything but the
 * identifier and the expiry.
 */

const { createHmac, randomUUID } = require("crypto");

const TOKEN_TTL_SECONDS = 90 * 24 * 60 * 60; // 90 days

/**
 * Mint a new server-side identity.
 *
 * The `u-` prefix distinguishes ids the server generated from the legacy
 * `local-*` ids the browser used to generate for itself. A client-supplied
 * identifier must never be signed: a signature only proves that *we* wrote the
 * claim, and says nothing about whether the claim was ever true.
 *
 * @returns {string}
 */
function newUserId() {
  return `u-${randomUUID()}`;
}

/**
 * Sign a session token for a user id.
 *
 * @param {string} userId
 * @param {string} secret                the MagicLink signing secret
 * @param {number} [nowSeconds]          injectable clock for tests
 * @returns {string|null}                null when unsigned (no secret or no id)
 */
function signSessionToken(userId, secret, nowSeconds = Math.floor(Date.now() / 1000)) {
  if (!secret || !userId) return null;
  const exp = nowSeconds + TOKEN_TTL_SECONDS;
  const payload = Buffer.from(JSON.stringify({ uid: userId, exp })).toString("base64url");
  const sig = createHmac("sha256", secret).update(payload).digest("base64url");
  return `${payload}.${sig}`;
}

/**
 * Verify a session token and return the user id it carries.
 *
 * @param {string} token
 * @param {string} secret                the MagicLink signing secret
 * @param {number} [nowSeconds]          injectable clock for tests
 * @returns {string|null}                the uid if valid and unexpired, else null
 */
function verifySessionToken(token, secret, nowSeconds = Math.floor(Date.now() / 1000)) {
  if (!secret || !token) return null;
  const parts = String(token).split(".");
  if (parts.length !== 2) return null;

  const [payload, sig] = parts;
  const expected = createHmac("sha256", secret).update(payload).digest("base64url");
  // NOTE: not a constant-time comparison. Tracked as hardening rather than fixed
  // here — the signal from a V8 string compare sits far below the noise floor of
  // API Gateway plus Lambda scheduling, and the route is throttled. Now that
  // there is exactly one copy, the fix is a one-line change in this file.
  if (sig !== expected) return null;

  try {
    const data = JSON.parse(Buffer.from(payload, "base64url").toString());
    if (!data.uid || !data.exp) return null;
    if (nowSeconds > data.exp) return null;
    return data.uid;
  } catch {
    return null;
  }
}

module.exports = {
  TOKEN_TTL_SECONDS,
  newUserId,
  signSessionToken,
  verifySessionToken,
};
